public class PriceCache {
    private final Map<String, BigDecimal> prices = new HashMap<>();
    private final ReentrantReadWriteLock rw = new ReentrantReadWriteLock();
    private final PriceLoader loader;

    public PriceCache(PriceLoader loader) { this.loader = loader; }

    public BigDecimal get(String sku) {
        rw.readLock().lock();
        try {
            BigDecimal price = prices.get(sku);
            if (price == null) {
                rw.writeLock().lock();
                try {
                    price = loader.load(sku);
                    prices.put(sku, price);
                } finally {
                    rw.writeLock().unlock();
                }
            }
            return price;
        } finally {
            rw.readLock().unlock();
        }
    }
}

fix.code:
public BigDecimal get(String sku) {
    rw.readLock().lock();
    try {
        BigDecimal price = prices.get(sku);
        if (price != null) return price;
    } finally {
        rw.readLock().unlock();          // nhả read trước khi xin write
    }
    rw.writeLock().lock();
    try {
        // thread khác có thể đã nạp trong lúc ta chờ: kiểm tra lại
        return prices.computeIfAbsent(sku, loader::load);
    } finally {
        rw.writeLock().unlock();
    }
}

// Gọn hơn và nhanh hơn cho trường hợp này: bỏ lock, dùng ConcurrentHashMap
private final Map<String, BigDecimal> prices = new ConcurrentHashMap<>();
public BigDecimal get(String sku) {
    return prices.computeIfAbsent(sku, loader::load);
